      "id": "route-legality",
      "expression": "legal = routeConnected AND passageAuthorized AND segmentPassable",
      "status": "approved-Seoul-bounded",
      "authority": "GP-02-A direction plus existing physical-adjacency and no-teleport locks",
      "rounding": "none",
      "clamp": "none",
      "rng": "none",
      "limits": "Unknown predicate produces unresolved. A map line, same-name station or surface adjacency cannot substitute for any guard.",
      "unit": "boolean | unresolved"
    },
    {
      "id": "segment-residual",
      "expression": "remainingAfter = max(0, remainingBefore - traversedDistance); arrived = legal AND remainingAfter = 0",
      "status": "approved-conservation-shape-with-held-rate",
      "authority": "actual-movement lock and sealed GP-02-A blocked-segment replanning direction",
      "rounding": "none in documentary exact arithmetic",
      "clamp": "lower bound 0 only",
      "rng": "none",
      "limits": "traversedDistance must be externally established by an approved rate/table. This formula does not approve strategic speed, fatigue or terrain coefficients.",
      "unit": "same route-defined distance unit; arrived boolean"
    },
    {
      "id": "cargo-split-conservation",
      "expression": "parentAtoms = disjointUnion(childAtoms); active parent retires; active child quantity sum equals parent quantity",
      "status": "approved-Seoul-bounded",
      "authority": "selected split-provenance policy and material conservation",
      "rounding": "none; atom identities are indivisible in this proof",
      "clamp": "none",
