  "stateGuards": {
    "estate": "alive -> no inheritance; dead+missing law/allocation -> held; dead+eligible explicit whole allocation -> title-transferred-awaiting-delivery",
    "delivery": "reserved -> in-transit -> arrived-unconfirmed/quarantined -> verified-received; no physical advance from title transfer",
    "obligation": "active/held/ended/needs-ratification/fulfilled per authored clause; missing clause held"
  },
  "mechanisms": [
    {
      "id": "D13-ESTATE",
      "source": [
        "sp1.b64",
        "sp1.b65",
        "sp1.b67",
        "T68-D13-FAMILY-ASSETS"
      ],
      "read": [
        "death",
        "registeredTestament",
        "legalEligibility",
        "authorizedWholeAllocations",
        "assets",
        "debts"
      ],
      "write": [
        "assets.owner",
        "estateStatus",
        "deliveryObligation",
        "causeHistory"
      ],
      "steps": [
        "Fix personal estate list excluding institutional assets and persons.",
        "Mark existing liens, reservations and disputes.",
        "If law/valid testament/authorized whole allocation missing, retain prior owner and held record; never distribute residue equally.",
        "For explicitly authorized eligible whole assets transfer title only; preserve quantity, custodian, location, route, use rights, reservation, lien.",
        "Record delivery obligation separately; no inventory addition.",
        "Retain recorded personal obligor and estate-review debt; never blanket heir liability."
      ],
      "cancel": "No applied title transition is undone by cancelling a later delivery; unapplied allocations remain held.",
      "death": "Death opens estate; living permanent detention does not. Beneficiary death triggers fresh D12/D09 eligibility, not fallback allocation.",
      "load": "Restore source cause IDs and applied result once; incompatible rules fail without partial load."
    },
    {
      "id": "D13-SPLIT",
      "source": [
        "sp1.b62",
        "sp1.b65",
        "GP-06/split-provenance-A"
      ],
      "read": [
        "parent",
        "children",
        "materialUnit",
        "approvedPartition"
      ],
      "write": [
        "parent.retired",
        "children",
        "splitProvenance"
      ],
      "steps": [
        "Require divisible parent and exactly two fresh child identities.",
        "Check child atom sets are disjoint and their union equals parent atoms; units identical.",
        "Preserve title, custody, rights, reservations, liens, route and location in children.",
        "Retire parent to immutable history; count only active child stock."
      ],
      "cancel": "Before commit unchanged; after split parent remains history, no reactivation by cancellation.",
      "death": "Title inheritance does not repeat physical split.",
      "load": "Reject duplicate atom/live parent ownership counting; keep lineage."
    },
    {
      "id": "D13-RESERVE",
      "source": [
        "sp1.b12",
        "sp1.b125",
        "offer-reservation-B",
        "GP-06/reservation-conflict-B"
      ],
      "read": [
        "offer",
        "acceptance",
        "authority",
        "snapshot",
        "assets.reservation",
        "priceVersion",
        "contract"
      ],
      "write": [
        "assets.reservation",
        "resultHistory"
      ],
      "steps": [
        "Proposal alone never reserves.",
        "Require registered price and accepted contract snapshot; no V<=W automatic acceptance.",
        "Revalidate authority, same snapshot and unique asset identities/atoms.",
        "On valid acceptance atomically reserve all requested assets, or preserve all previous reservations on conflict.",
        "Competing acceptance gets typed conflict and explicit re-proposal requirement; no queue."
      ],
      "cancel": "Reservation release follows the signed contract clause, not a universal auto-release.",
      "death": "Revalidate remaining authority/obligations; preserve completed effects.",
      "load": "Restore one exclusive reservation per material identity."
    },
    {
      "id": "D13-DELIVERY",
      "source": [
        "sp1.b65",
        "economy-owner.20261003.arrival",
        "GP-06/custody-receipt-A"
      ],
      "read": [
        "D06.actualArrival",
        "receiverConfirmation",
        "identityRightsValidation",
        "otherReceiptConditions",
        "cutoff",
        "reservation"
      ],
      "write": [
        "assets.custodian",
        "assets.location",
        "deliveryState",
        "receiptHistory"
      ],
      "steps": [
        "Legal title alone cannot alter location or custody.",
        "Verified actual arrival plus designated recipient confirmation, valid identity/custody/rights and applicable conditions completes receipt.",
        "No mandatory separate custodian signature added: stronger two-party conjunction remains proposal.",
        "Confirmed arrival <= cutoff is eligible at that cutoff; late arrival never changes past cutoff.",
        "Failure receipt stays physically local/quarantined and unavailable; missing delivery keeps reservation.",
        "Preserve completed receipt against later failed retry or blockade; distinct admitted events follow D18 causal/ingress ordering."
      ],
      "cancel": "Before receipt use delivery contract; after receipt no silent erasure or teleport refund.",
      "death": "Revalidate recipient/authority; no auto substitute recipient.",
      "load": "Restore accepted receipt and location once; duplicate arrival typed rejection."
    },
    {
      "id": "D13-OBLIGATIONS",
      "source": [
        "sp1.b64",
        "D06/GP-13",
        "D11/T68-D16-ORGANIZATION-LIFECYCLE",
        "D19/T68-D11-CONTRACT-RECALL"
      ],
      "read": [
        "attachment",
        "legalRepresentative",
        "contractClauses",
        "expiry",
        "death",
        "ratification"
      ],
      "write": [
        "obligationStatus"
      ],
      "steps": [
        "Keep personal/office/institution attachment distinct.",
        "Land loss does not erase organization identity, treasury, debt or obligations.",
        "Missing lawful representative/custodian/dissolution clause produces held state, not deletion.",
        "Evaluate actual signed continue/end/ratify clause; record legal effect and physical handover separately.",
        "No new debt priority, interest, automatic recall, return or heir reassignment."
      ],
      "cancel": "Clause-specific; missing clause held.",
      "death": "Recorded attachment persists pending lawful resolution.",
      "load": "Identity and fulfilled stages retained; no whole-completion from one stage receipt."
    }
